#include <iostream>
#include <string>

int main() {
    std::string str;
    std::getline(std::cin, str);
    while (str.length() > 2 && str.substr(1, str.length() - 2).find("dot") != std::string::npos) {
        size_t index_dot = str.find("dot", 1);
        str = str.substr(0, index_dot) + "." + str.substr(index_dot + 3);
    }
    size_t index_at = str.find("at", 1);
    if (index_at != std::string::npos) {
        str = str.substr(0, index_at) + "@" + str.substr(index_at + 2);
    }
    std::cout << str << std::endl;
    return 0;
}
